/// 🖨️ Emits a declared physical record through caller-owned output admission.
pub fn print_controlled(value:&RecordValue,spec:&RecordSpec,mode:JoinMode,maximum_output_bytes:usize,control:&mut NativeEncodeControl<'_>)->Result<String,TextError>{
