use super::*;
macro_rules! ordinary_fixture_spec {
    ($spec:path) => { crate::RecordSpecProducer { ordinary: $spec, decoding: |_| Err("ordinary-only test metadata has no controlled construction".into()), encoding: |_| Err("ordinary-only test metadata has no controlled construction".into()) } };
