    fn to_value_controlled(&self,control:&mut NativeEncodeControl<'_>)->Result<FieldValue,String>{control.step().map_err(|error|error.into_message())?;Ok(FieldValue::Text(control.copy_text(self).map_err(|error|error.into_message())?))}
